<script setup lang="ts">
import axios from 'axios'; import { computed, onMounted, ref } from 'vue';
const props = defineProps<{ occasionId: number | null }>(); const emit = defineEmits<{ cancel: []; saved: [] }>(); const tab = ref<'general'|'recurrence'|'validity'>('general'); const loading = ref(false); const saving = ref(false); const error = ref(''); const title = computed(() => props.occasionId === null ? 'Novo feriado' : 'Editar feriado'); const form = ref({ name:'', occasionCategory:'HOLIDAY', territorialScope:'COUNTRY', locality:{ countryId:'' }, validity:{ from:'', to:'' }, recurrence:{ type:'ANNUAL_FIXED_DATE' } });
async function load(){if(props.occasionId===null)return;loading.value=true;try{Object.assign(form.value,(await axios.get(`/api/v1/platform/calendar-occasions/${props.occasionId}`)).data)}catch{error.value='Não foi possível carregar esta definição.'}finally{loading.value=false}} async function save(){saving.value=true;error.value='';try{props.occasionId===null?await axios.post('/api/v1/platform/calendar-occasions',form.value):await axios.patch(`/api/v1/platform/calendar-occasions/${props.occasionId}`,form.value);emit('saved')}catch{error.value='Não foi possível salvar a definição.'}finally{saving.value=false}} onMounted(()=>void load());
</script>
<template><section class="calendar-occasion-form"><header><h3>{{ title }}</h3></header><form @submit.prevent="save"><p v-if="error" role="alert">{{ error }}</p><nav><button type="button" :aria-selected="tab==='general'" @click="tab='general'">Geral</button><button type="button" :aria-selected="tab==='recurrence'" @click="tab='recurrence'">Recorrência</button><button type="button" :aria-selected="tab==='validity'" @click="tab='validity'">Vigência e substituição</button></nav><fieldset :disabled="loading||saving"><div v-show="tab==='general'"><label>Nome<input v-model="form.name" required></label><label>Categoria<select v-model="form.occasionCategory"><option value="HOLIDAY">Feriado</option><option value="OPTIONAL_DAY_OFF">Ponto facultativo</option><option value="COMMEMORATIVE_DATE">Data comemorativa</option></select></label><label>Esfera<select v-model="form.territorialScope"><option value="COUNTRY">País</option><option value="BRAZIL_STATE">Estado brasileiro</option><option value="BRAZIL_MUNICIPALITY">Município brasileiro</option></select></label></div><div v-show="tab==='recurrence'"><label>Tipo de recorrência<select v-model="form.recurrence.type"><option value="ANNUAL_FIXED_DATE">Anual em data fixa</option><option value="ONE_TIME_DATE">Data única</option><option value="ANNUAL_NTH_WEEKDAY">Dia ordinal da semana</option><option value="EASTER_OFFSET">Deslocamento da Páscoa</option></select></label></div><div v-show="tab==='validity'"><label>Início<input v-model="form.validity.from" type="date"></label><label>Fim<input v-model="form.validity.to" type="date"></label></div></fieldset><footer><button class="ui-button ui-button--secondary" type="button" @click="emit('cancel')">Cancelar</button><button class="ui-button ui-button--primary" type="submit" :disabled="saving">{{saving?'Salvando…':'Salvar'}}</button></footer></form></section></template>
<style scoped>.calendar-occasion-form{display:grid;grid-template-rows:auto minmax(0,1fr);min-height:100%;overflow:hidden}.calendar-occasion-form header{padding:var(--space-3) var(--space-4);border-bottom:1px solid var(--color-border-subtle)}h3{margin:0}form{display:grid;grid-template-rows:auto auto minmax(0,1fr) auto;gap:var(--space-3);padding:var(--component-workspace-surface-padding);overflow:hidden}nav{display:flex;overflow:auto;border-bottom:1px solid var(--color-border-subtle)}nav button{padding:var(--space-3);border:0;border-bottom:2px solid transparent;background:transparent}nav button[aria-selected=true]{border-bottom-color:var(--color-action-primary)}fieldset{overflow:auto;border:0}fieldset>div{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--space-3)}label{display:grid;gap:var(--space-1)}input,select{min-height:var(--control-height-sm);padding:var(--space-2);border:1px solid var(--color-border-subtle);border-radius:var(--radius-sm);background:var(--color-surface-raised);color:var(--color-text-primary)}footer{display:flex;justify-content:end;gap:var(--space-2)}@media(max-width:700px){fieldset>div{grid-template-columns:1fr}}</style>
